    private void executeScannerTask() {

        HomeBankingLoadDTO homeBankingLoadDTO = performDataBase.loadHomeBanking(this.botJobLoad.getHomeBankingId());

        try {
            Platform.runLater(() -> {
                try {
                    // Call the ABRScannedElementScene here
                    ABRScannedElementScene scene = abrScannedElementScene.initialize(
                            homeBankingLoadDTO.getPriority(),
                            this.botJobLoad.getId(),
                            this.botJobLoad.getBlockLoadDTOList() != null
                                            && this.botJobLoad
                                                            .getBlockLoadDTOList()
                                                            .size()
                                                    > 0
                                    ? this.botJobLoad
                                            .getBlockLoadDTOList()
                                            .get(0)
                                            .getId()
                                    : null);

                    scene.show(); // Make sure the scene is shown
                } catch (Exception ex) {
                    handleExceptionScan(ex);
                }
            });
        } catch (Exception ex) {
            handleExceptionScan(ex);
        }
    }

    private void handleExceptionScan(Exception ex) {
        // Log the exception
        ABRLogger.getInstance(ABRWebDriver.class)
                .severe("ERROR Calling openScannerButton -> Cause: " + ex.getMessage());

        // Display the error message to the user
        if (ex.getMessage().contains("no such window: target window already closed")
                || ex.getMessage().contains("web view not found")) {
            performMessage.errorMessage(
                    "Error Calling SCAN",
                    "Web Browser was closed before the Scanner Tool",
                    "Close and Re-Open the Scanner Tool",
                    null,
                    null,
                    0);
        } else {

            if (ex.getMessage().contains("Current browser version")) {
                String[] lines = ex.getMessage().split("\n");
                String msg1 = "";
                String msg2 = "";

                for (String line : lines) {
                    int indexMessage = line.indexOf("Message: ");
                    if (indexMessage != -1) {
                        msg1 = line.substring(indexMessage + "Message: ".length());
                    }

                    int indexBrowserVersion = line.indexOf("Current browser version");
                    if (indexBrowserVersion != -1) {
                        msg2 = line.substring(indexBrowserVersion);
                    }
                }

                ABRLogger.getInstance(ABRViewBotJobPane.class).severe("Error Open URL: \n" + msg1 + "\n" + msg2);

                performMessage.errorMessage("Error WebDriver Version", msg1, msg2, null, null, 260);
            }
        }

        //        Platform.runLater(() -> {
        //            JOptionPane.showMessageDialog(
        //                    null,
        //                    "An error has occurred Calling SCAN: \nCause: " + ex.getMessage(),
        //                    "Error calling in SCAN",
        //                    JOptionPane.ERROR_MESSAGE);
        //        });
    }

    private void showAlert(String title, String content) {
        executorService = Executors.newSingleThreadExecutor();
        alertToShow.setAlertType(AlertType.ERROR);
        alertToShow.setTitle("Error");
        alertToShow.setHeaderText(title);
        alertToShow.setContentText(content);

        executorService.execute(() -> {
            timeline.setCycleCount(SECONDS); // Run for seconds
            timeline.play(); // Start the timeline

            // Show the alert on the JavaFX Application Thread
            javafx.application.Platform.runLater(() -> alertToShow.showAndWait());
        });

        if (executorService != null) {
            remainingSeconds = SECONDS;
            executorService.shutdown();
        }
    }

